--[[
  NIGHTDLC · packed · night_pc_fixed
]]

do
	local name = "Unknown"
	local ok, a = pcall(function()
		if type(identifyexecutor) == "function" then return identifyexecutor() end
		if type(getexecutorname) == "function" then return getexecutorname() end
	end)
	if ok and type(a) == "string" and a ~= "" then name = a end
	if type(getgenv) == "function" then getgenv().NIGHTDLC_EXECUTOR = name end
	print("[NIGHTDLC] packed · " .. name)
end

local function _ndlc_decode(payload, key)
	local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	payload = payload:gsub("[^" .. alphabet .. "=]", "")
	local data = {}
	local build = {}
	local function push(n)
		table.insert(build, string.char(n))
		if #build >= 4096 then
			table.insert(data, table.concat(build))
			build = {}
		end
	end
	for i = 1, #payload, 4 do
		local a = alphabet:find(payload:sub(i, i), 1, true) or 1
		local b = alphabet:find(payload:sub(i + 1, i + 1), 1, true) or 1
		local c = alphabet:find(payload:sub(i + 2, i + 2), 1, true) or 1
		local d = alphabet:find(payload:sub(i + 3, i + 3), 1, true) or 1
		a, b, c, d = a - 1, b - 1, c - 1, d - 1
		local n = a * 262144 + b * 4096 + c * 64 + d
		push(math.floor(n / 65536) % 256)
		if payload:sub(i + 2, i + 2) ~= "=" then push(math.floor(n / 256) % 256) end
		if payload:sub(i + 3, i + 3) ~= "=" then push(n % 256) end
	end
	if #build > 0 then table.insert(data, table.concat(build)) end
	local raw = table.concat(data)
	local out = {}
	local chunk = {}
	local klen = #key
	for i = 1, #raw do
		local byte = string.byte(raw, i)
		local kb = key[((i - 1) % klen) + 1]
		local x, y = byte, kb
		local r, p2 = 0, 1
		while x > 0 or y > 0 do
			local xb, yb = x % 2, y % 2
			if xb ~= yb then r = r + p2 end
			x, y, p2 = (x - xb) / 2, (y - yb) / 2, p2 * 2
		end
		table.insert(chunk, string.char(r))
		if #chunk >= 4096 then
			table.insert(out, table.concat(chunk))
			chunk = {}
		end
	end
	if #chunk > 0 then table.insert(out, table.concat(chunk)) end
	return table.concat(out)
end

local _KEY = {233,4,34,155,9,74,165,12,128,251,169,82,12,88,204,37,116,200,76,208,71,206,130,123,64,181,32,134,145,7,103,8}
local _PAYLOAD = [==[]==]

local src = _ndlc_decode(_PAYLOAD, _KEY)
local fn, err = loadstring(src)
if not fn then
	warn("[NIGHTDLC] unpack failed: " .. tostring(err))
	return
end
fn()
